<?php require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/auth.php';require_page('medicines.php');$page_title='Stok Obat';$page_subtitle='Inventory management hanya oleh apoteker: katalog, stok minimum, harga, expiry, dan status.';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'&&is_role('pharmacist')){check_csrf();$code=trim($_POST['code']);$name=trim($_POST['name']);$unit=trim($_POST['unit']);$stock=(int)$_POST['stock'];$min=(int)$_POST['min_stock'];$price=(float)$_POST['price'];$expiry=$_POST['expiry_date'];if($code===''||$name===''||$unit===''||$stock<0||$min<0||$price<0||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$expiry))$msg='Data obat tidak valid.';else{try{$s=$pdo->prepare('INSERT INTO medicines(code,name,category,unit,stock,min_stock,expiry_date,price,is_active) VALUES(?,?,?,?,?,?,?,?,1)');$s->execute([$code,$name,$_POST['category'], $unit,$stock,$min,$expiry,$price]);audit($pdo,'CREATE','MEDICINE',(int)$pdo->lastInsertId(),'Obat ditambahkan ke inventory.');$msg='Obat berhasil ditambahkan.';}catch(Throwable $e){$msg='Kode obat sudah digunakan atau data tidak sesuai.';}}}$rows=$pdo->query('SELECT * FROM medicines ORDER BY (stock<=min_stock) DESC,name')->fetchAll();include __DIR__.'/includes/header.php';?><?php if($msg):?><div class="alert <?=str_contains($msg,'berhasil')?'success':'danger'?>"><?=h($msg)?></div><?php endif;?><div class="grid two"><div class="card"><div class="card-header"><div><h3 class="section-title">Add Medicine</h3><p class="section-subtitle">Master obat dan stok hanya dapat diubah apoteker.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><div><label>Kode</label><input name="code" required></div><div><label>Nama</label><input name="name" required></div><div><label>Kategori</label><input name="category"></div><div><label>Unit</label><input name="unit" required></div><div><label>Stok</label><input type="number" min="0" name="stock" required></div><div><label>Minimum Stok</label><input type="number" min="0" name="min_stock" required></div><div><label>Harga</label><input type="number" min="0" name="price" required></div><div><label>Expiry</label><input type="date" name="expiry_date" required></div><div><button class="btn primary">+ Simpan Obat</button></div></form></div><div class="card"><div class="card-header"><div><h3 class="section-title">Inventory Snapshot</h3><p class="section-subtitle"><?=count($rows)?> obat aktif/tercatat.</p></div></div><div class="table-wrap"><table><tr><th>Kode</th><th>Obat</th><th>Stok</th><th>Min</th><th>Expiry</th><th>Status</th></tr><?php foreach($rows as $r):$low=$r['stock']<=$r['min_stock'];$expired=$r['expiry_date']<date('Y-m-d');?><tr><td><?=h($r['code'])?></td><td><?=h($r['name'])?></td><td><?=h((string)$r['stock'])?> <?=h($r['unit'])?></td><td><?=h((string)$r['min_stock'])?></td><td><?=h($r['expiry_date'])?></td><td><span class="badge <?=$expired?'danger':($low?'warn':'ok')?>"><?=$expired?'EXPIRED':($low?'LOW STOCK':'AMAN')?></span></td></tr><?php endforeach;?></table></div></div></div><?php include __DIR__.'/includes/footer.php';?>